() => {
  const aside = document.querySelector('aside, [class*="sidebar"], nav');
  // Find sidebar menu buttons
  const buttons = Array.from(document.querySelectorAll('button')).filter(b => {
    const r = b.getBoundingClientRect();
    return r.left < 260 && r.width > 150 && r.top > 100 && r.top < 600;
  });
  const results = [];
  for (const btn of buttons) {
    const spans = btn.querySelectorAll('span, div, p');
    const info = { btnText: btn.textContent.trim().slice(0, 40), items: [] };
    // get line height info for each text element
    const walk = (el) => {
      const style = getComputedStyle(el);
      const txt = el.textContent.trim();
      if (!txt) return;
      const direct = Array.from(el.childNodes).some(n => n.nodeType === 3 && n.textContent.trim());
      if (direct || el.children.length === 0) {
        const lh = parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.2;
        const lines = Math.round(el.getBoundingClientRect().height / lh);
        info.items.push({
          text: txt.slice(0, 30),
          lines,
          whiteSpace: style.whiteSpace,
          overflow: style.overflow,
          textOverflow: style.textOverflow,
          w: Math.round(el.getBoundingClientRect().width)
        });
      }
    };
    btn.querySelectorAll('*').forEach(walk);
    results.push(info);
  }
  return results;
}

() => {
  const aside = document.querySelector('aside') || Array.from(document.querySelectorAll('div,nav,aside')).find(e => {
    const r = e.getBoundingClientRect();
    return r.left === 0 && r.width <= 270 && r.height > 500;
  });
  if (!aside) return 'not found';
  aside.setAttribute('data-shot-target', '1');
  const r = aside.getBoundingClientRect();
  return { w: r.width, h: r.height, tag: aside.tagName };
}
